import { MissionPlan } from '@mavsdk/mavsdk';

const items = [];
const altitude = 20;

// Zone 1 (E130 N0): Three lawnmower passes (N-S orientation)
// Passes at east: 105, 130, 155 (25m spacing)
// Each pass runs north from -30 to +30 (60m length)
const eastPositions = [105, 130, 155];
const northPositions = [-30, 30];

log('Building Zone 1 lawnmower mission: 3 passes × 60m');

for (const east of eastPositions) {
  for (const north of northPositions) {
    const geo = await world_to_geo(east, north, altitude);
    items.push(mission_item({
      latitude_deg: geo.lat,
      longitude_deg: geo.lon,
      relative_altitude_m: altitude
    }));
  }
}

const mission = new MissionPlan(items);
await drone.upload_mission(mission);
await arm_and_start();
log('Drone 0 (Zone 1) survey complete');

